import {squadPlan} from './squad-planner.js';
import {displayDate} from './manager-calendar.js';
import {renderSquadPlan} from './squad-planner-ui.js';
import {positionCareer,positionProfile} from './manager-positions.js';
import {careerAvailability,availabilityText} from './career-availability.js';
import {availabilityPanel} from './availability-ui.js';
import {POSITION_SLOTS,canPlayPosition} from './player-positions.js';
import {positionLabel} from './player-positions.js';
import {escapeHtml as esc} from './ui-kit.js';
import {FORMATIONS} from './engine.js';
import {legend} from './legends.js';
import {managerOwned,managerReadiness} from './manager-career.js';
import {managerView,nextManagerFixture,managerPrimary,opponentBrief} from './manager-experience.js';
import {playerDossier} from './player-dossier.js';
import {action,viewButton as v,commandButton as b,managerCard as card,managerColor,managerForm as form,select,managerFace as face,managerTabs as tabs,energy} from './manager-ui-kit.js';

export function renderSquad(c,pending){
 const s=managerView(c),all=managerOwned(c),slot=Number.isInteger(s.slot)&&s.slot>=0&&s.slot<11?s.slot:null,selected=all.includes(s.player)?s.player:c.xi[slot??0],p=positionCareer(c)?positionProfile(legend(selected)):legend(selected),f=nextManagerFixture(c),primary=managerPrimary(c,pending),plan=squadPlan(c),issue=c.xi.find(id=>c.condition[id].contract<=0||careerAvailability(c,id));
 const prep=s.preparing?`<section class="mgr-preparation card"><div><span class="eyebrow highlight">MATCHDAY · ${f?.homeGame?'HOME':'AWAY'}</span><h2 tabindex="-1" data-view-focus>${f?'Prepare for '+esc(f.opponent.name):'Your match plan'}</h2><p>${f?esc(f.competitionName)+' · '+displayDate(f.date)+' · ':''}${c.formation} · ${esc(c.management.preset)} · ${c.xi.filter(id=>c.condition[id].energy<75).length} starters below 75% energy</p><p class="mgr-prep-selection">${issue?esc(legend(issue).name)+' needs a replacement or contract review.':plan&&!plan.canFieldXI?'Missing cover: '+esc(plan.missing.join(', ')):'No unavailable or expired player in the selected XI.'}</p></div><div class="mgr-actions">${pending||c.xi.some(id=>c.condition[id].contract<=0)||c.event?action(primary.label,primary.action,primary.id||'','primary'):(positionCareer(c)?action('Play yourself','eu-career-direct','','primary')+action('Manage live','eu-career-manage','','secondary'):action('Manage next fixture','eu-career-manage','','primary'))}${!pending&&!c.event&&!c.xi.some(id=>c.condition[id].contract<=0)?action('Simulate next matchday','eu-career-quick','','secondary'):''}</div><small>Manage live or choose Play yourself at kickoff. Keyboard and touch controls are available for new fixtures. Simulation produces a fast statistical result.</small><div class="mgr-actions">${action('Practise controls','training-ground','','ghost')}</div>${opponentPanel(c,f)}</section>`:'';
 const nav=tabs([['lineup','Lineup'],...(positionCareer(c)?[['planning','Squad planner']]:[]),['tactics','Tactics'],['teams','Team sheets'],['bench','Match bench'],['player','Player detail']],s.squadTab,'squad-tab');
 if(s.proposal)return prep+nav+proposal(c,s.proposal);
 const selectedSlot=c.xi.indexOf(selected),coverEligible=id=>c.condition[id].contract>0&&!careerAvailability(c,id)&&(positionCareer(c)?selectedSlot>=0&&canPlayPosition(positionProfile(legend(id)),POSITION_SLOTS[c.formation][selectedSlot]):legend(id).role===p.role);
 const pitch=`<div class="mgr-squad-layout"><section class="mgr-team-board"><div class="mgr-section-top"><div><span class="eyebrow">YOUR STARTING XI</span><h2>${c.formation}</h2></div>${v('Compare rotation','rotation')}</div><div class="mgr-selection-pitch" aria-label="Select a starting player"><div class="mgr-pitch-lines" aria-hidden="true"><i></i><i></i></div>${FORMATIONS[c.formation].map((position,i)=>{const id=c.xi[i],q=legend(id),absence=careerAvailability(c,id);return `<button class="mgr-pitch-player ${id===selected?'selected':''}" style="left:${Math.max(12,Math.min(88,position.x))}%;top:${position.y}%" data-action="eu-view-slot" data-value="${i}" aria-label="${esc(q.name+', '+q.role+', '+(absence?availabilityText(absence):Math.round(c.condition[id].energy)+'% energy'))}" aria-pressed="${id===selected}"><span class="mgr-pitch-face">${face(q)}</span><strong>${esc(q.name.split(' ').at(-1))}</strong>${absence?'<small class="manager-contract-alert">'+(absence.kind==='injured'?'Injured':'Suspended')+'</small>':energy(c,id)}</button>`;}).join('')}</div><div class="mgr-actions">${v('Formation & saved teams','squad-tab','teams')}</div></section>${card('PLAYER & POSITION',p.name,`${face({...p,color:managerColor(c)})}<div class="mgr-player-summary"><span>${esc(positionLabel(p))} · ${Math.round(managerReadiness(c,selected).base)} OVR</span>${energy(c,selected)}<p>${esc(managerReadiness(c,selected).label)} · morale ${Math.round(c.condition[selected].morale)} · ${c.condition[selected].appearances||0} appearances</p></div>${selectedSlot>=0?`<h3>Compare cover</h3>${c.bench.filter(coverEligible).map(id=>`<div class="mgr-cover"><div><strong>${esc(legend(id).name)}</strong><small>${Math.round(managerReadiness(c,id).base)} OVR · ${Math.round(c.condition[id].energy)}% energy${c.condition[id].contract<=0?' · expired':''}</small></div>${v('Compare','cover',id)}</div>`).join('')||'<p>No reserve in this position. Review recruitment.</p>'}`:''}${s.cover&&c.bench.includes(s.cover)&&coverEligible(s.cover)?`<section class="mgr-comparison"><h3>${esc(legend(s.cover).name)}</h3><p>${Math.round(managerReadiness(c,s.cover).base)} OVR vs ${Math.round(managerReadiness(c,selected).base)} · energy ${Math.round(c.condition[s.cover].energy)}% vs ${Math.round(c.condition[selected].energy)}%</p><p>A change trades ability, condition and club familiarity. ${positionCareer(c)?'This replacement covers the selected natural position.':'Legacy lineup eligibility uses broad roles; check each player’s natural positions before applying.'}</p>${v('Start '+legend(s.cover).name,'swap',s.cover,'primary')}</section>`:''}${v('Player development & contract','squad-tab','player')}`,'mgr-selected-player')}</div>`;
 return prep+nav+availabilityPanel(c)+(s.squadTab==='planning'&&positionCareer(c)?renderSquadPlan(c):s.squadTab==='tactics'?tactics(c):s.squadTab==='teams'?teamSheets(c):s.squadTab==='bench'?bench(c):s.squadTab==='player'?playerDetail(c,selected):pitch)+`<div class="mgr-training"><label>Weekly preparation<select id="career-training" ${pending?'disabled':''}>${[['balanced','Balanced · steady recovery'],['recovery','Recovery first · fresher legs'],['development','Development · less recovery']].map(([id,name])=>`<option value="${id}" ${c.training===id?'selected':''}>${name}</option>`).join('')}</select></label><p>Recovery and development follow the existing matchday rules.</p></div>`+(s.proposal?proposal(c,s.proposal):'');
}
function opponentPanel(c,f){const b=opponentBrief(c,f);if(!b)return '';const roles=Object.entries(b.cover).map(([role,n])=>n+' '+role).join(' · ');return `<details class="mgr-opponent"><summary>Opposition briefing</summary><span class="eyebrow">WHAT YOU KNOW</span><p><strong>${esc(b.name)}</strong> · ${b.home?'You are at home':'You are away'}${b.rating==null?'':' · strength '+b.rating}${b.attack==null?'':' · attack '+b.attack}${b.defense==null?'':' · defense '+b.defense}${b.formation?' · '+esc(b.formation):''}</p><p>${b.last?'Last recorded meeting: '+(b.last.home?'Home':'Away')+' '+b.last.score.join('–')+'.':'No previous meeting is recorded in this save.'}${roles?' Selected roles: '+esc(roles)+'.':''} Figures reflect this save; tactical effects remain game estimates.</p></details>`;}
function proposal(c,d){return card('SUGGESTED XI','Review the changes',`<p>${d.mode==='rotation'?'Freshness is weighted alongside ability.':'The highest-rated eligible players are selected.'} Your current team stays in place until you apply this proposal.</p><div class="mgr-proposed-team">${d.xi.map((id,i)=>`<div><span>${FORMATIONS[d.formation][i].role}</span><strong>${esc(legend(id).name)}</strong><small>${Math.round(c.condition[id].energy)}% energy${c.xi[i]!==id?' · change':''}</small></div>`).join('')}</div>${v('Apply proposed XI','apply-proposal','','primary')}${v('Keep current team','cancel-proposal')}`);}
function teamSheets(c){return card('TEAM SHEETS','A shape for your squad',`<form data-manager-view-form="proposal"><div class="manager-form-grid"><label>New formation${select('formation',Object.keys(FORMATIONS).map(f=>[f,f]),c.formation)}</label><label>Selection${select('mode',[['strongest','Strongest eligible XI'],['rotation','Favor fresh legs']],'strongest')}</label></div><button class="btn primary">Preview team</button></form><div class="manager-sheets">${['Strongest','Rotation','Custom'].map((name,i)=>`<div><h3>${name}</h3><p>${c.management.sheets[i]?esc(c.management.sheets[i].formation)+' · saved':'No team saved'}</p>${b('Save '+name,'sheet-save',i)}${b('Load '+name,'sheet-load',i)}</div>`).join('')}</div><details><summary>Manual lineup editor</summary>${form('lineup',`<label>Formation${select('formation',[[c.formation,c.formation]],c.formation)}</label><div class="manager-lineup">${FORMATIONS[c.formation].map((slot,i)=>`<label>${i+1} · ${slot.role}${select('xi'+i,managerOwned(c).filter(id=>positionCareer(c)?canPlayPosition(positionProfile(legend(id)),POSITION_SLOTS[c.formation][i]):legend(id).role===slot.role).map(id=>[id,legend(id).name+' · '+(careerAvailability(c,id)?availabilityText(careerAvailability(c,id)):Math.round(c.condition[id].energy)+'%')]),c.xi[i])}</label>`).join('')}</div>`)}</details>`);}
function bench(c){return card('MATCH BENCH','Your cover for matchday',`<p>Choose up to nine contracted reserves. Other squad players stay at the club.</p>${form('bench',c.bench.map(id=>`<label class="mgr-bench-choice"><input name="reserve" type="checkbox" value="${id}" ${(c.management.matchBench||c.bench.slice(0,9)).includes(id)&&!careerAvailability(c,id)?'checked':''} ${c.condition[id].contract<=0||careerAvailability(c,id)?'disabled':''}><span><strong>${esc(legend(id).name)}</strong><small>${esc(positionLabel(legend(id)))} · ${Math.round(c.condition[id].energy)}% energy${careerAvailability(c,id)?' · '+esc(availabilityText(careerAvailability(c,id))):''}</small></span></label>`).join(''))}`);}
function playerDetail(c,id){const p=positionCareer(c)?positionProfile(legend(id)):legend(id),s=c.condition[id];return card('SQUAD PLAYER',p.name,`<label>Choose squad player<select data-manager-view-select="player">${managerOwned(c).map(q=>`<option value="${q}" ${q===id?'selected':''}>${esc(legend(q).name)}</option>`).join('')}</select></label><div class="mgr-profile-identity">${face({...p,color:managerColor(c)})}<div><h3>${esc(positionLabel(p))} · ${Math.round(managerReadiness(c,id).base)} OVR</h3><p>${Math.round(s.energy)}% energy · ${Math.round(s.morale)} morale · form ${(s.form||0).toFixed(1)}</p><p>${s.appearances||0}/${s.eligible||0} appearances · ${esc(s.promise||'rotation')} promise</p><p>Readiness adjustment ${managerReadiness(c,id).modifier.toFixed(1)} · energy applied separately</p></div></div>${form('focus',`<label>Development focus${select('value',[['balanced','Balanced'],['attack','Finishing'],['control','Passing & touch'],['defense','Defending / keeping'],['recovery','Recovery']],s.focus)}</label>`,id)}${playerDossier(p,c)}${v('Review contract','contracts',id)}`);}
function tactics(c){const m=c.management;return card('TACTICAL IDENTITY','Give the team a plan',`<p>High press uses more energy. Protect reduces attacking support. Instructions carry into managed matches.</p><div class="manager-tactics-grid"><div class="mgr-tactic-options">${[['balanced','Balanced','Keep options open.'],['press','High press','Recover higher; spend more energy.'],['protect','Protect','Stay compact; commit fewer players.']].map(([id,name,copy])=>`<div class="mgr-tactic-option ${m.preset===id?'selected':''}"><h3>${name}</h3><p>${copy}</p></div>`).join('')}</div>${form('tactics',`<label>Approach${select('preset',[['balanced','Balanced'],['press','High press'],['protect','Protect']],m.preset)}</label><label>Build-up${select('build',[['mixed','Mixed'],['short','Short · safer lanes'],['direct','Direct · earlier forward passes']],m.build)}</label><details><summary>Individual responsibilities</summary>${c.xi.slice(1).map((id,j)=>`<label>${esc(legend(id).name)}${select('role'+(j+1),[['hold','Hold'],['support','Support'],['attack','Attack']],m.roles[j+1]||'support')}</label>`).join('')}</details>`)}</div>`);}



